($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 11428962, $f$Briny Depths$f$, ARRAY[$f$kittensandcake$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$They say the whale-god eats those mutineers left to drift the oceans.$f$, 2833, 1, 1, true, -1, false, $f$2019-07-07T20:40:46.663+00:00$f$, $f$2019-07-07T20:40:46.757+00:00$f$, $f$2017-07-07T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 11433414, $f$God In the Blood$f$, ARRAY[$f$dreabean$f$, $f$Troodon$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$The Outsider, long used to being a program, hardly remembers his time in the Void that Was. It died when he did, and everything that was magic went with it. Delilah, in search of more power, more augments, and more destruction, cares little for the gods of old and Emily is the one who has to pay the price.And now, the Void is waking up.$f$, 91537, 13, 13, true, -1, true, $f$2019-07-16T11:13:34.813+00:00$f$, $f$2019-07-16T11:13:34.894+00:00$f$, $f$2017-07-07T00:00:00.000+00:00$f$, false, false, true, $f$25619841$f$, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 11445489, $f$Isle of Wolves$f$, ARRAY[$f$Eione$f$]::text[], ARRAY[$f$The Silmarillion and other histories of Middle-Earth - J. R. R. Tolkien$f$]::text[], NULL, ARRAY[]::text[], $f$In Tol-in-Gaurhoth, Sauron forces Beren to rape Finrod for his amusement with an audience of Orcs looking on. Finrod experiences an involuntary mental bond from the rape and feels Beren's physical pleasure as his own.$f$, 3226, 1, 1, true, 3, false, $f$2019-07-29T22:25:58.979+00:00$f$, $f$2019-07-29T22:25:59.048+00:00$f$, $f$2017-07-23T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 11448099, $f$from now our merge is eternal$f$, ARRAY[$f$Psuedorabbit$f$]::text[], ARRAY[$f$ジョジョの奇妙な冒険 | JoJo no Kimyou na Bouken | JoJo's Bizarre Adventure$f$]::text[], NULL, ARRAY[]::text[], NULL, NULL, 1, 1, true, -1, false, $f$2018-07-02T11:23:42.600+00:00$f$, $f$2018-07-02T11:23:42.777+00:00$f$, $f$2017-07-09T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
