($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 11802981, $f$The Pit of Madness$f$, ARRAY[$f$jenni4765$f$]::text[], ARRAY[$f$The Silmarillion and other histories of Middle-Earth - J. R. R. Tolkien$f$]::text[], NULL, ARRAY[]::text[], $f$The action is set in Tol-in-Gaurhoth, with Finrod and Beren imprisoned by Sauron.  While Finrod tries to stay alive amid repeated attacks, Beren is determined to prevail.$f$, 2722, 1, 1, true, 3, false, $f$2019-07-29T21:43:30.795+00:00$f$, $f$2019-07-29T21:43:30.836+00:00$f$, $f$2017-08-14T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
