($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 11864358, $f$Some Day I'm Gonna Marry You$f$, ARRAY[$f$Nuinzilien$f$]::text[], ARRAY[$f$The Silmarillion and other histories of Middle-Earth - J. R. R. Tolkien$f$]::text[], NULL, ARRAY[]::text[], $f$The first of the Noldor elves to encounter Men was Finrod Felagund, who befriended the Men of Beor, learning their ways and language, and teaching them his own.  This is how the Ring of Finrod came to be an heirloom of Barahir's line.$f$, 5282, 1, 1, true, 1, false, $f$2019-07-28T17:00:45.491+00:00$f$, $f$2019-07-28T17:00:45.569+00:00$f$, $f$2017-08-21T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[])
